function lowerBound(values, target) {
  let low = 0
  let high = values.length - 1
  let answer = values.length
  while (low <= high) {
    const mid = low + Math.floor((high - low) / 2)
    if (values[mid] >= target) {
      answer = mid
      high = mid - 1
    } else {
      low = mid + 1
    }
  }
  return answer
}

